      const req = t.request(p, {
        method,
        headers: method === 'POST' ? { 'Content-Type': 'application/json' } : {},
        ...(method === 'POST' ? { body: JSON.stringify({}) } : {})
      });
      const res = await req;
      assert.equal(res.status, 401, `${method} ${p} should be 401 without token`);
