/**
 * Admin Service – HTTP Routes
 *
 * Authenticated administrator-only question CRUD. Mounted under
 * /api/admin by the gateway (and directly on this service).
 *
 *   POST   /api/admin/questions            – create question (201)
 *   GET    /api/admin/questions            – list questions (includes correct_answer)
 *   GET    /api/admin/questions/:id        – single question (includes correct_answer)
 *   PUT    /api/admin/questions/:id        – update question
 *   DELETE /api/admin/questions/:id        – delete question (204)
 *
 * Authorization: every route requires a valid Bearer OIDC access token AND
 * the `admin` realm role. Unauthenticated requests yield 401; authenticated
 * non-admin requests yield 403 (per the acceptance contract).
 *
 * Server-side validation:
 *   - prompt must be a non-empty string
 *   - options must be an array of 2..10 non-empty strings
 *   - correctAnswer must be a well-formed exact rational ("a/b" or integer)
 *   - correctAnswer must be one of options (the correct answer is always a
 *     listed option, matching the multiple-choice model)
 */

const { Router } = require('express');
const { requireAuth, requireAdmin } = require('@spacefractions/shared/auth');
const {
  BadRequestError,
  NotFoundError,
  ConflictError,
} = require('@spacefractions/shared/errors');
const { query, queryOne } = require('@spacefractions/shared/db');
const { isValidFraction, fractionsEqual, formatFraction } = require('@spacefractions/shared/fraction');
const { questionsCreated } = require('@spacefractions/shared/metrics');
const { indexQuestion, deleteQuestion: deleteQuestionDoc } = require('../../question-service/src/search');

const { resolveInternalUserId } = require('@spacefractions/shared/identity');

const router = Router();

const LIMIT_MAX = 500;
const OPTIONS_MIN = 2;
const OPTIONS_MAX = 10;

/**
 * Normalize and validate a question payload ({ prompt, options, correctAnswer }).
 * Returns the normalized { prompt, options, correctAnswer } on success.
 * Throws BadRequestError for malformed input.
 */
function validateQuestionPayload(body) {
  if (typeof body !== 'object' || body === null) {
    throw new BadRequestError('Request body must be a JSON object');
  }

  const { prompt, options, correctAnswer } = body;

  // prompt: non-empty string with a length cap
  if (typeof prompt !== 'string' || prompt.trim() === '') {
    throw new BadRequestError('prompt must be a non-empty string');
  }
  if (prompt.length > 2000) {
    throw new BadRequestError('prompt exceeds maximum length of 2000 characters');
  }

  // options: array of 2..10 non-empty strings, no duplicates (after trim)
  if (!Array.isArray(options)) {
    throw new BadRequestError('options must be an array of strings');
  }
  if (options.length < OPTIONS_MIN || options.length > OPTIONS_MAX) {
    throw new BadRequestError(
      `options must contain between ${OPTIONS_MIN} and ${OPTIONS_MAX} strings`
    );
  }
  const seen = new Set();
  for (const opt of options) {
    if (typeof opt !== 'string' || opt.trim() === '') {
      throw new BadRequestError('each option must be a non-empty string');
    }
    if (opt.length > 200) {
      throw new BadRequestError('an option exceeds maximum length of 200 characters');
    }
    if (seen.has(opt.trim())) {
      throw new BadRequestError('options must not contain duplicates');
    }
    seen.add(opt.trim());
  }

  // correctAnswer: well-formed exact fraction AND one of the options
  if (typeof correctAnswer !== 'string' || correctAnswer.trim() === '') {
    throw new BadRequestError('correctAnswer must be a non-empty string');
  }
  if (!isValidFraction(correctAnswer)) {
    throw new BadRequestError(
      'correctAnswer must be a well-formed fraction ("a/b", denominator != 0)'
    );
  }
  // The correct answer must appear among the options (compare as exact
  // rationals so "1/2" and "2/4" are considered the same answer).
  const normalizedCorrect = formatFraction(correctAnswer);
  const optionMatches = options.some((opt) => fractionsEqual(opt, correctAnswer));
  if (!optionMatches) {
    throw new BadRequestError('correctAnswer must be one of the provided options');
  }

  return {
    prompt: prompt.trim(),
    options,
    correctAnswer: normalizedCorrect,
  };
}

/**
 * Serialize a question row for admin responses (includes correct_answer).
 */
function toAdminQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: row.options,
    correctAnswer: row.correct_answer,
    createdBy: row.created_by,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/**
 * Resolve the internal user id for the authenticated caller (from OIDC `sub`).
 * Used to stamp `created_by` on new questions and to authorize ownership.
 */
async function resolveCallerUserId(claims) {
  const sub = claims && claims.sub;
  if (!sub) {
    throw new BadRequestError('Token missing subject (sub) claim');
  }
  const row = await queryOne('SELECT id FROM users WHERE sub = $1', [sub]);
  return row ? row.id : null;
}

// Apply auth middlewares to all admin routes. Order matters: requireAuth
// populates req.user, then requireAdmin enforces the realm role.
router.use(requireAuth, requireAdmin);

/**
 * GET /api/admin/questions
 * List all questions (with correct_answer), newest first. Optional ?limit.
 */
router.get('/questions', async (req, res, next) => {
  try {
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : LIMIT_MAX;
    if (Number.isNaN(limit) || limit < 1 || limit > LIMIT_MAX) {
      throw new BadRequestError(`limit must be between 1 and ${LIMIT_MAX}`);
    }

    const result = await query(
      `SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at
       FROM questions
       ORDER BY created_at DESC
       LIMIT $1`,
      [limit]
    );

    res.json({
      questions: result.rows.map(toAdminQuestion),
      count: result.rows.length,
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /api/admin/questions/:id
 * Single question (with correct_answer).
 */
router.get('/questions/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid question id');
    }

    const row = await queryOne(
      `SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at
       FROM questions WHERE id = $1`,
      [id]
    );

    if (!row) {
      throw new NotFoundError('Question not found');
    }

    res.json(toAdminQuestion(row));
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/admin/questions
 * Create a question. Body: { prompt, options: [string], correctAnswer }.
 * Returns 201 with the created question.
 */
router.post('/questions', async (req, res, next) => {
  try {
    const normalized = validateQuestionPayload(req.body);
    const createdBy = await resolveCallerUserId(req.user);

    const result = await query(
      `INSERT INTO questions (prompt, options, correct_answer, created_by)
       VALUES ($1, $2, $3, $4)
       RETURNING id, prompt, options, correct_answer, created_by, created_at, updated_at`,
      [
        normalized.prompt,
        JSON.stringify(normalized.options),
        normalized.correctAnswer,
        createdBy,
      ]
    );

    const row = result.rows[0];

    // Best-effort Elasticsearch indexing (non-fatal).
    try {
      await indexQuestion({ id: row.id, prompt: row.prompt, options: row.options });
    } catch (err) {
      console.warn('Admin service: index question failed:', err.message);
    }

    questionsCreated.inc();

    res.status(201).json(toAdminQuestion(row));
  } catch (err) {
    next(err);
  }
});

/**
 * PUT /api/admin/questions/:id
 * Update (replace) a question. Same validation as create.
 */
router.put('/questions/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid question id');
    }

    const existing = await queryOne('SELECT id FROM questions WHERE id = $1', [id]);
    if (!existing) {
      throw new NotFoundError('Question not found');
    }

    const normalized = validateQuestionPayload(req.body);

    const result = await query(
      `UPDATE questions
       SET prompt = $2, options = $3, correct_answer = $4, updated_at = NOW()
       WHERE id = $1
       RETURNING id, prompt, options, correct_answer, created_by, created_at, updated_at`,
      [
        id,
        normalized.prompt,
        JSON.stringify(normalized.options),
        normalized.correctAnswer,
      ]
    );

    const row = result.rows[0];

    try {
      await indexQuestion({ id: row.id, prompt: row.prompt, options: row.options });
    } catch (err) {
      console.warn('Admin service: index question failed:', err.message);
    }

    res.json(toAdminQuestion(row));
  } catch (err) {
    next(err);
  }
});

/**
 * DELETE /api/admin/questions/:id
 * Delete a question. Returns 204 No Content on success.
 */
router.delete('/questions/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid question id');
    }

    const result = await query('DELETE FROM questions WHERE id = $1 RETURNING id', [id]);

    if (result.rows.length === 0) {
      throw new NotFoundError('Question not found');
    }

    try {
      await deleteQuestionDoc(id);
    } catch (err) {
      console.warn('Admin service: delete question doc failed:', err.message);
    }

    res.status(204).end();
  } catch (err) {
    next(err);
  }
});

module.exports = router;
module.exports.validateQuestionPayload = validateQuestionPayload;
module.exports.toAdminQuestion = toAdminQuestion;

/**
 * OAuth2/OIDC authentication middleware and utilities.
 *
 * Validates JWT access tokens against an OIDC provider using RS256
 * signature verification (jose), plus issuer/audience/expiry/nbf checks.
 *
 * Configuration (via configure()):
 *   - ORIGIN_ISSUER / OIDC_ISSUER      required issuer (e.g. Keycloak realm)
 *   - OIDC_CLIENT_ID                   optional
 *   - OIDC_AUDIENCE                    required audience (default "account")
 *   - OIDC_JWKS_URI                    explicit JWKS endpoint
 *   - jwks                             KeySet: a JWKS object `{ keys: [...] }`
 *                                      or a single JWK, used for *local*
 *                                      verification (tests / offline). Takes
 *                                      precedence over remote discovery.
 *
 * When only an issuer is configured without an explicit jwks/jwksUri, the
 * JWKS endpoint is discovered via the OIDC well-known document and used to
 * build a remote JWK set.
 */

const jose = require('jose');
const { UnauthorizedError, ForbiddenError } = require('./errors');

/** OIDC configuration state (null until configured). */
let oidcConfig = null;
/** Cached remote/local JWK set used for signature verification. */
let keySet = null;

/**
 * Fetch a remote JWKS document (also used by tests for key extraction).
 */
async function fetchJWKS(jwksUri) {
  let resp;
  try {
    resp = await fetch(jwksUri, { signal: AbortSignal.timeout(5000) });
  } catch (err) {
    throw new Error(`JWKS fetch failed: ${err.message}`);
  }
  if (!resp.ok) {
    throw new Error(`JWKS fetch failed: ${resp.status}`);
  }
  return resp.json();
}

/**
 * Find a key in a JWKS by kid.
 */
function findKey(jwks, kid) {
  if (!jwks || !Array.isArray(jwks.keys)) return null;
  return jwks.keys.find((k) => k.kid === kid) || null;
}

/**
 * Decode base64url to Uint8Array.
 */
function base64urlDecode(str) {
  const base64 = str.replace(/-/g, '+').replace(/_/g, '/');
  const padded = base64 + '==='.slice(0, (4 - (base64.length % 4)) % 4);
  const binary = atob(padded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/**
 * Parse a JWT into { header, payload, signature } without verification.
 * Used for header inspection only.
 */
function decodeJWT(token) {
  const parts = String(token).split('.');
  if (parts.length !== 3) {
    throw new Error('Invalid JWT format');
  }
  const header = JSON.parse(new TextDecoder().decode(base64urlDecode(parts[0])));
  const payload = JSON.parse(new TextDecoder().decode(base64urlDecode(parts[1])));
  return { header, payload, signature: parts[2] };
}

/**
 * Configure OIDC validation.
 *
 * @param {object} config - overrides; any value also falls back to the
 *   corresponding OIDC_* / ORIGIN_ISSUER environment variable.
 */
function configure(config = {}) {
  const env = process.env;
  const issuer =
    config.OIDC_ISSUER || config.ORIGIN_ISSUER || env.OIDC_ISSUER || env.ORIGIN_ISSUER || null;
  const clientId = config.OIDC_CLIENT_ID || env.OIDC_CLIENT_ID || null;
  const audience =
    config.OIDC_AUDIENCE ||
    env.OIDC_AUDIENCE ||
    config.AUDIENCE ||
    env.AUDIENCE ||
    'account';
  const jwksUri = config.OIDC_JWKS_URI || env.OIDC_JWKS_URI || null;
  const jwks = config.jwks || (env.OIDC_JWKS ? safeParseJson(env.OIDC_JWKS) : null);

  if (!issuer) {
    // Truly unconfigured: token validation must fail loudly rather than
    // silently accepting any structurally-valid token.
    oidcConfig = null;
    keySet = null;
    return;
  }

  oidcConfig = {
    issuer,
    clientId,
    audience,
    jwksUri,
    jwks: toJWKSObject(jwks)
  };

  // Build the verification key set eagerly when a local JWKS is supplied.
  if (oidcConfig.jwks) {
    keySet = jose.createLocalJWKSet(oidcConfig.jwks);
  } else {
    keySet = null; // resolved lazily via remote discovery
  }
}

function safeParseJson(str) {
  try {
    return JSON.parse(str);
  } catch {
    return null;
  }
}

/** Normalize a JWK or a JWKS `{keys:[...]}` into a JWKS object. */
function toJWKSObject(value) {
  if (!value) return null;
  if (Array.isArray(value.keys)) return value;
  // A bare JWK (has kty) -> wrap as a single-key JWKS.
  if (value && value.kty) return { keys: [value] };
  return null;
}

/** Resolve the JWKS endpoint from the configured issuer (well-known). */
async function getJwksUri() {
  const issuer = oidcConfig && oidcConfig.issuer;
  if (!issuer) return null;
  if (oidcConfig.jwksUri) return oidcConfig.jwksUri;

  try {
    const resp = await fetch(`${issuer.replace(/\/$/, '')}/.well-known/openid-configuration`, {
      signal: AbortSignal.timeout(5000)
    });
    if (resp.ok) {
      const meta = await resp.json();
      oidcConfig.jwksUri = meta.jwks_uri;
      return oidcConfig.jwksUri;
    }
  } catch {
    /* fall through to Keycloak default */
  }
  oidcConfig.jwksUri = `${issuer.replace(/\/$/, '')}/protocol/openid-connect/certs`;
  return oidcConfig.jwksUri;
}

/** Return (and lazily build) the jose key set used for signature checks. */
async function getKeySet() {
  if (keySet) return keySet;
  const jwksUri = await getJwksUri();
  if (jwksUri) {
    keySet = jose.createRemoteJWKSet(new URL(jwksUri));
  }
  return keySet;
}

/**
 * Validate an OIDC Bearer token.
 *
 * Performs full RS256 signature verification against the configured JWKS and
 * enforces issuer / audience / expiration / not-before. Returns the decoded
 * payload on success and throws UnauthorizedError on any failure.
 */
async function validateToken(token) {
  if (!oidcConfig) {
    throw new UnauthorizedError('OIDC not configured');
  }

  const raw = token.startsWith('Bearer ') ? token.slice(7) : token;

  let header;
  try {
    header = decodeJWT(raw).header;
  } catch {
    throw new UnauthorizedError('Invalid token format');
  }

  // If a key set is available (local JWKS or discoverable remote), verify the
  // signature. Without it, fall back to claim checks only.
  const ks = await getKeySet();
  if (ks) {
    try {
      const { payload } = await jose.jwtVerify(raw, ks, {
        algorithms: ['RS256'],
        issuer: oidcConfig.issuer,
        audience: oidcConfig.audience
      });
      return payload;
    } catch (err) {
      // jose throws for both signature and claim failures; map to 401.
      throw new UnauthorizedError(`Token verification failed: ${err.message}`);
    }
  }

  // No key set available: perform structural + claim validation only.
  const { payload } = decodeJWT(raw);

  const now = Math.floor(Date.now() / 1000);
  if (payload.exp && payload.exp < now) {
    throw new UnauthorizedError('Token expired');
  }
  if (payload.nbf && payload.nbf > now) {
    throw new UnauthorizedError('Token not yet valid');
  }
  if (oidcConfig.issuer && payload.iss !== oidcConfig.issuer) {
    throw new UnauthorizedError(`Invalid issuer: expected ${oidcConfig.issuer}, got ${payload.iss}`);
  }
  const aud = payload.aud;
  const expectedAud = oidcConfig.audience;
  if (expectedAud) {
    const audList = Array.isArray(aud) ? aud : [aud];
    if (!audList.includes(expectedAud)) {
      throw new UnauthorizedError(`Invalid audience: expected ${expectedAud}`);
    }
  }
  void header;
  return payload;
}

/**
 * Express middleware that requires a valid Bearer token.
 */
function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return next(new UnauthorizedError('Missing or invalid Authorization header'));
  }

  validateToken(authHeader)
    .then((payload) => {
      req.user = payload;
      next();
    })
    .catch((err) => {
      next(err instanceof UnauthorizedError ? err : new UnauthorizedError(err.message));
    });
}

/**
 * Express middleware that requires the admin role. Use after requireAuth.
 */
function requireAdmin(req, res, next) {
  if (!req.user) {
    return next(new UnauthorizedError('Authentication required'));
  }

  const roles = (req.user && req.user.realm_access && req.user.realm_access.roles) || [];
  if (!roles.includes('admin')) {
    return next(new ForbiddenError('Admin role required'));
  }

  next();
}

/**
 * Optional auth: sets req.user when a valid token is present, never fails.
 */
function optionalAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return next();
  }

  validateToken(authHeader)
    .then((payload) => {
      req.user = payload;
      next();
    })
    .catch(() => next());
}

module.exports = {
  configure,
  validateToken,
  requireAuth,
  requireAdmin,
  optionalAuth,
  decodeJWT,
  fetchJWKS,
  findKey
};

/**
 * Gateway – Routes
 *
 * Single entrypoint (port 3000) that forwards to the four internal services.
 *
 * Downstream service base URLs are resolved from environment with sensible
 * Compose defaults so the gateway works both in `docker compose up` and when
 * services are run locally on distinct ports.
 */

const { Router } = require('express');
const path = require('path');
const { proxyRequest, probeService } = require('./middleware');

const router = Router();

// Downstream base URLs (Compose service names by default).
const GAME_SERVICE_URL = process.env.GAME_SERVICE_URL || 'http://localhost:3001';
const QUESTION_SERVICE_URL = process.env.QUESTION_SERVICE_URL || 'http://localhost:3002';
const USER_SERVICE_URL = process.env.USER_SERVICE_URL || 'http://localhost:3003';
const ADMIN_SERVICE_URL = process.env.ADMIN_SERVICE_URL || 'http://localhost:3004';

/**
 * Wrap a downstream call and forward its status/body/headers to the client.
 * Downstream AppError payloads are preserved verbatim.
 */
function forward(baseUrl, strippedPathBuilder) {
  return async (req, res, next) => {
    try {
      const strippedPath = strippedPathBuilder(req);
      const result = await proxyRequest(baseUrl, strippedPath, req);
      res.status(result.status).json(result.body);
    } catch (err) {
      next(err);
    }
  };
}

