function renderMenu({ isAdmin }) {
  const view = clearView();
  view.innerHTML = `
    <div class="card center">
      <h1>Main Menu</h1>
      <ul class="menu-list">
        <li><button class="btn" data-action="play">Play</button></li>
        <li><button class="btn" data-action="score">View Score</button></li>
