/**
 * Integration test helpers for Space Fractions.
 *
 * Purpose: allow HTTP-boundary integration tests of the real service route
 * modules WITHOUT requiring live PostgreSQL/Redis/RabbitMQ/Keycloak.
 *
 * Strategy:
 *   - Inject a fake `@spacefractions/shared/db` (in-memory row store) into the
 *     require cache, plus fake cache/mq modules, so the real route handlers
 *     exercise real request/response/error-handling logic.
 *   - Use the REAL auth module (`validateToken` performs structural + issuer/
 *     audience/expiry checks; signature verification is exercised by the
 *     separate acceptance/auth profile). We craft local JWTs for known
 *     identities (admin/student).
 *   - Mount the real router into a fresh Express app and serve over HTTP on an
 *     ephemeral port, driving each request with `fetch`.
 *
 * These files live under test/integration/ and are invoked via
 * `npm run test:integration` (node --test). They do not require full
 * infrastructure; the full stack is exercised by compose and the auth profile.
 */

const express = require('express');
const path = require('node:path');
const crypto = require('node:crypto');
const { once } = require('node:events');

const DB_MODULE_PATH = require.resolve('@spacefractions/shared/db');
const CACHE_MODULE_PATH = require.resolve('@spacefractions/shared/cache');
const MQ_MODULE_PATH = require.resolve('@spacefractions/shared/mq');
const AUTH_MODULE_PATH = require.resolve('@spacefractions/shared/auth');

const ISSUER = 'http://keycloak:8080/realms/spacefractions';
const AUDIENCE = 'account';

/**
 * Build a fake in-memory DB implementing the query surface used by services.
 * The store is a plain object with arrays for games/questions/answers/users.
 * `query`/`queryOne` implement a small SQL pattern matcher sufficient for the
 * route handlers under test. Unknown SQL throws so coverage gaps surface.
 */
function createFakeDb(initialState = {}) {
  const store = {
    users: [],
    questions: [],
    games: [],
    answers: [],
    nextGameId: 1,
    nextQuestionId: 1,
    nextAnswerId: 1,
    nextUserId: 1,
    ...initialState
  };

  function findGame(id) { return store.games.find((g) => g.id === id); }

  function handleQuery(sql, params = []) {
    const s = sql.trim();

    // ----- games -----
    if (/SELECT \* FROM games WHERE id = \$1$/.test(s)) {
      return { rows: store.games.filter((g) => g.id === params[0]) };
    }
    if (/SELECT id FROM questions ORDER BY created_at/.test(s)) {
      return { rows: store.questions.map((q) => ({ id: q.id })) };
    }
    if (/INSERT INTO games \(/.test(s)) {
      // params: [user_id, state, score, question_ids, current_question_index]
      const game = {
        id: store.nextGameId++,
        user_id: params[0],
        state: params[1],
        score: params[2],
        question_ids: params[3],
        current_question_index: params[4]
      };
      store.games.push(game);
      return { rows: [game] };
    }
    if (/UPDATE games SET state = 'paused'/.test(s)) {
      const game = findGame(params[0]);
      if (game && game.state === 'playing') { game.state = 'paused'; return { rows: [game] }; }
      return { rows: [] };
    }
    if (/^UPDATE games SET state = 'playing'/.test(s)) {
      const game = findGame(params[0]);
      if (game && game.state === 'paused') { game.state = 'playing'; return { rows: [game] }; }
      return { rows: [] };
    }
    if (/UPDATE games SET score = score \+ \$1/.test(s)) {
      const game = findGame(params[1]);
      if (game) game.score += params[0];
      return { rows: [game] };
    }
    if (/UPDATE games SET current_question_index = \$1, state = \$2/.test(s)) {
      const game = findGame(params[2]);
      if (game) { game.current_question_index = params[0]; game.state = params[1]; }
      return { rows: [game] };
    }
    if (/UPDATE games SET current_question_index = \$1, state = \$2, updated_at/.test(s)) {
      const game = findGame(params[2]);
      if (game) { game.current_question_index = params[0]; game.state = params[1]; }
      return { rows: [game] };
    }

    // ----- questions -----
    if (/SELECT id, prompt, options FROM questions WHERE id = \$1$/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]).map(q => ({ id: q.id, prompt: q.prompt, options: q.options })) };
    }
    if (/SELECT id, correct_answer FROM questions WHERE id = \$1/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]).map(q => ({ id: q.id, correct_answer: q.correct_answer })) };
    }
    if (/SELECT id, prompt, options, created_at, updated_at\s*FROM questions WHERE id = \$1/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]).map(q => ({ id: q.id, prompt: q.prompt, options: q.options, created_at: q.created_at, updated_at: q.updated_at })) };
    }
    if (/SELECT id, prompt, options FROM questions ORDER BY created_at DESC LIMIT \$1/.test(s)) {
      return { rows: store.questions.map(q => ({ id: q.id, prompt: q.prompt, options: q.options })).slice(0, params[0]) };
    }
    if (/SELECT id, prompt, options FROM questions WHERE id = ANY/.test(s)) {
      const ids = params[0] || [];
      return { rows: store.questions.filter(q => ids.includes(q.id)).map(q => ({ id: q.id, prompt: q.prompt, options: q.options })) };
    }
    if (/FROM questions\s+ORDER BY created_at DESC\s+LIMIT \$1\b/.test(s)) {
      return { rows: store.questions.map(q => ({ id: q.id, prompt: q.prompt, options: q.options })).slice(0, params[0]) };
    }
    if (/INSERT INTO questions \(prompt, options, correct_answer, created_by\)/.test(s)) {
      const row = {
        id: store.nextQuestionId++,
        prompt: params[0],
        options: JSON.parse(params[1]),
        correct_answer: params[2],
        created_by: params[3],
        created_at: new Date('2024-01-01T00:00:00Z'),
        updated_at: new Date('2024-01-01T00:00:00Z')
      };
      store.questions.push(row);
      return { rows: [row] };
    }
    if (/SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at\s*FROM questions ORDER BY created_at DESC LIMIT \$1/.test(s)) {
      return { rows: store.questions.map(q => ({ ...q })).slice(0, params[0]) };
    }
    if (/SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at\s*FROM questions WHERE id = \$1/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]) };
    }
    if (/UPDATE questions\s+SET prompt = \$2, options = \$3, correct_answer = \$4/.test(s)) {
      const q = store.questions.find((x) => x.id === params[0]);
      if (q) { q.prompt = params[1]; q.options = JSON.parse(params[2]); q.correct_answer = params[3]; }
      return { rows: [q] };
    }
    if (/DELETE FROM questions WHERE id = \$1 RETURNING id/.test(s)) {
      const idx = store.questions.findIndex((x) => x.id === params[0]);
      if (idx === -1) return { rows: [] };
      const [rm] = store.questions.splice(idx, 1);
      return { rows: [{ id: rm.id }] };
    }
    if (/SELECT id FROM questions WHERE id = \$1$/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]).map(q => ({ id: q.id })) };
    }

    // ----- game_answers -----
    if (/SELECT \* FROM game_answers WHERE game_id = \$1 AND question_id = \$2/.test(s)) {
      return { rows: store.answers.filter(a => a.game_id === params[0] && a.question_id === params[1]) };
    }
    if (/INSERT INTO game_answers /.test(s)) {
      const id = store.nextAnswerId++;
      const row = { id, game_id: params[0], question_id: params[1], answer: params[2], correct: params[3], scored: params[4] };
      // unique (game_id, question_id) upsert emulation
      const existing = store.answers.find(a => a.game_id === row.game_id && a.question_id === row.question_id);
      if (existing) {
        existing.answer = row.answer;
        existing.correct = row.correct || existing.correct;
        existing.scored = existing.scored || row.scored;
        return { rows: [existing] };
      }
      store.answers.push(row);
      return { rows: [row] };
    }
    if (/UPDATE game_answers SET answer = \$1, correct = TRUE, scored = TRUE WHERE id = \$2/.test(s)) {
      const row = store.answers.find(a => a.id === params[1]);
      if (row) { row.answer = params[0]; row.correct = true; row.scored = true; }
      return { rows: [row] };
    }

    // ----- users -----
    if (/SELECT \* FROM users WHERE sub = \$1/.test(s)) {
      return { rows: store.users.filter(u => u.sub === params[0]) };
    }
    if (/SELECT id FROM users WHERE sub = \$1/.test(s)) {
      return { rows: store.users.filter(u => u.sub === params[0]).map(u => ({ id: u.id })) };
    }
    if (/INSERT INTO users \(sub, username, email\)/.test(s)) {
      const row = { id: store.nextUserId++, sub: params[0], username: params[1], email: params[2], created_at: new Date('2024-01-01T00:00:00Z') };
      store.users.push(row);
      return { rows: [row] };
    }

    throw new Error(`Unexpected SQL in integration fake DB: ${sql.slice(0, 120)}`);
  }

  return {
    store,
    query: async (sql, params) => handleQuery(sql, params),
    queryOne: async (sql, params) => {
      const r = await handleQuery(sql, params);
      return r.rows[0] || null;
    }
  };
}

/**
 * Fake cache (in-memory Map). get/set/del/healthCheck enough for handlers.
 */
function createFakeCache() {
  const map = new Map();
  return {
    get: async (k) => (map.has(k) ? map.get(k) : null),
    set: async (k, v) => { map.set(k, v); },
    del: async (k) => { map.delete(k); },
    healthCheck: async () => true
  };
}

/**
 * Fake MQ: records published score events, expose publishScoreUpdated.
 */
function createFakeMQ() {
  const events = [];
  return {
    events,
    publishScoreUpdated: async (gameId, userId, score, questionId) => {
      events.push({ gameId, userId, score, questionId });
    }
  };
}

/**
 * Build a JWT header/payload/signature string for the REAL validateToken.
 *
 * The auth module now performs full RS256 signature verification via jose.
 * To keep these HTTP-boundary integration tests fully offline (no live
 * Keycloak), we generate a local RSA key pair synchronously, sign every
 * token with the private half, and expose the public JWK set so tests can
 * seed the auth module via `configure({ jwks: publicJWKS })`.
 *
 * `crypto.sign('RSA-SHA256', ...)` produces the same RS256 signature that
 * `jose.SignJWT(...).sign(...)` would, but synchronously — which lets us keep
 * `makeToken` (and the ADMIN_TOKEN/STUDENT_TOKEN/OTHER_TOKEN factories)
 * synchronous so every existing call site stays unchanged.
 */
function b64url(obj) {
  return Buffer.from(JSON.stringify(obj)).toString('base64url');
}

const KID = 'integration-key';
const { privateKey, publicKey } = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });

/** Public JWK set (matching the private signing key) for auth.configure(). */
const jwk = publicKey.export({ format: 'jwk' });
const publicJWKS = {
  keys: [{ ...jwk, alg: 'RS256', use: 'sig', kid: KID }]
};

function signJwt(payloadObj) {
  const header = b64url({ alg: 'RS256', typ: 'JWT', kid: KID });
  const payload = b64url(payloadObj);
  const signingInput = `${header}.${payload}`;
  const signature = crypto
    .sign('RSA-SHA256', Buffer.from(signingInput), privateKey)
    .toString('base64url');
  return `${signingInput}.${signature}`;
}

function makeToken(claims, opts = {}) {
  const payload = {
    iss: claims.iss ?? ISSUER,
    aud: claims.aud ?? AUDIENCE,
    exp: claims.exp ?? Math.floor(Date.now() / 1000) + 3600,
    sub: claims.sub,
    preferred_username: claims.preferred_username || claims.sub,
    email: claims.email,
    realm_access: claims.realm_access || { roles: claims.roles || [] },
    ...claims
  };
  return signJwt(payload);
}

const ADMIN_TOKEN = () => makeToken({ sub: 'admin-user-sub', roles: ['admin', 'user'] });
const STUDENT_TOKEN = () => makeToken({ sub: 'student-user-sub', roles: ['user'] });
const OTHER_TOKEN = () => makeToken({ sub: 'other-user-sub', roles: ['user'] });

/**
 * Build an Express app with the provided router mounted at `mountPath`,
 * JSON parsing, and the shared error handler. Returns the started server and
 * a base URL plus helpers to make requests and stop the server.
 */
async function startApp(router, mountPath = '/api/games') {
  const app = express();
  app.use(express.json());
  app.use(mountPath, router);
  const { errorHandler } = require('@spacefractions/shared/errors');
  app.use(errorHandler);

  const server = app.listen(0);
  await once(server, 'listening');
  const port = server.address().port;
  const baseUrl = `http://127.0.0.1:${port}`;

  return {
    server,
    baseUrl,
    port,
    request: (subPath, options = {}) => fetch(`${baseUrl}${subPath}`, options),
    close: () => new Promise((resolve) => server.close(resolve))
  };
}

/**
 * Install fake modules into require cache and reload target route module(s).
 * Returns a restore function.
 */
function installFakes({ db, cache, mq, auth }) {
  const saved = {};
  const paths = { db: DB_MODULE_PATH, cache: CACHE_MODULE_PATH, mq: MQ_MODULE_PATH, auth: AUTH_MODULE_PATH };

  for (const [key, val] of Object.entries({ db, cache, mq, auth })) {
    const p = paths[key];
    if (!val) continue;
    saved[key] = require.cache[p];
    require.cache[p] = { id: p, filename: p, loaded: true, exports: val };
  }

  return function restore() {
    for (const [key, val] of Object.entries(saved)) {
      const p = paths[key];
      if (val === undefined) {
        delete require.cache[p];
      } else {
        require.cache[p] = val;
      }
    }
    if (db) delete require.cache[require.resolve('../../services/game-service/src/game-engine.js')];
    if (db) delete require.cache[require.resolve('../../services/game-service/src/routes.js')];
    delete require.cache[require.resolve('../../services/admin-service/src/routes.js')];
    delete require.cache[require.resolve('../../services/question-service/src/routes.js')];
    delete require.cache[require.resolve('../../services/user-service/src/routes.js')];
  };
}

/**
 * Seed questions matching the real seed (ids 1..3) with known correct answers.
 */
function seedQuestions(store) {
  const qs = [
    { id: 1, prompt: 'What is 1/2 + 1/4?', options: ['1/6', '3/4', '2/6', '1/8'], correct_answer: '3/4' },
    { id: 2, prompt: 'What is 3/5 - 1/5?', options: ['2/5', '4/5', '1/5', '3/10'], correct_answer: '2/5' },
    { id: 3, prompt: 'What is 2/3 x 3/4?', options: ['6/12', '5/7', '1/2', '2/4'], correct_answer: '1/2' }
  ];
  qs.forEach((q) => store.questions.push(q));
  store.nextQuestionId = 4;
  return qs;
}

function seedUsers(store) {
  const users = [
    { id: 1, sub: 'admin-user-sub', username: 'admin', email: 'admin@spacefractions.local' },
    { id: 2, sub: 'student-user-sub', username: 'student', email: 'student@spacefractions.local' },
    { id: 3, sub: 'other-user-sub', username: 'other', email: 'other@spacefractions.local' }
  ];
  users.forEach((u) => store.users.push({ ...u, created_at: new Date('2024-01-01T00:00:00Z') }));
  store.nextUserId = 4;
  return users;
}

module.exports = {
  ISSUER,
  AUDIENCE,
  publicJWKS,
  KID,
  dbPath: DB_MODULE_PATH,
  cachePath: CACHE_MODULE_PATH,
  mqPath: MQ_MODULE_PATH,
  authPath: AUTH_MODULE_PATH,
  createFakeDb,
  createFakeCache,
  createFakeMQ,
  makeToken,
  ADMIN_TOKEN,
  STUDENT_TOKEN,
  OTHER_TOKEN,
  startApp,
  installFakes,
  seedQuestions,
  seedUsers
};

/**
 * OAuth2/OIDC authentication middleware and utilities.
 *
 * Validates JWT access tokens against an OIDC provider using RS256
 * signature verification (jose), plus issuer/audience/expiry/nbf checks.
 *
 * Configuration (via configure()):
 *   - ORIGIN_ISSUER / OIDC_ISSUER      required issuer (e.g. Keycloak realm)
 *   - OIDC_CLIENT_ID                   optional
 *   - OIDC_AUDIENCE                    required audience (default "account")
 *   - OIDC_JWKS_URI                    explicit JWKS endpoint
 *   - jwks                             KeySet: a JWKS object `{ keys: [...] }`
 *                                      or a single JWK, used for *local*
 *                                      verification (tests / offline). Takes
 *                                      precedence over remote discovery.
 *
 * When only an issuer is configured without an explicit jwks/jwksUri, the
 * JWKS endpoint is discovered via the OIDC well-known document and used to
 * build a remote JWK set.
 */

const jose = require('jose');
const { UnauthorizedError, ForbiddenError } = require('./errors');

/** OIDC configuration state (null until configured). */
let oidcConfig = null;
/** Cached remote/local JWK set used for signature verification. */
let keySet = null;

/**
 * Fetch a remote JWKS document (also used by tests for key extraction).
 */
async function fetchJWKS(jwksUri) {
  let resp;
  try {
    resp = await fetch(jwksUri, { signal: AbortSignal.timeout(5000) });
  } catch (err) {
    throw new Error(`JWKS fetch failed: ${err.message}`);
  }
  if (!resp.ok) {
    throw new Error(`JWKS fetch failed: ${resp.status}`);
  }
  return resp.json();
}

/**
 * Find a key in a JWKS by kid.
 */
function findKey(jwks, kid) {
  if (!jwks || !Array.isArray(jwks.keys)) return null;
  return jwks.keys.find((k) => k.kid === kid) || null;
}

/**
 * Decode base64url to Uint8Array.
 */
function base64urlDecode(str) {
  const base64 = str.replace(/-/g, '+').replace(/_/g, '/');
  const padded = base64 + '==='.slice(0, (4 - (base64.length % 4)) % 4);
  const binary = atob(padded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/**
 * Parse a JWT into { header, payload, signature } without verification.
 * Used for header inspection only.
 */
function decodeJWT(token) {
  const parts = String(token).split('.');
  if (parts.length !== 3) {
    throw new Error('Invalid JWT format');
  }
  const header = JSON.parse(new TextDecoder().decode(base64urlDecode(parts[0])));
  const payload = JSON.parse(new TextDecoder().decode(base64urlDecode(parts[1])));
  return { header, payload, signature: parts[2] };
}

/**
 * Configure OIDC validation.
 *
 * @param {object} config - overrides; any value also falls back to the
 *   corresponding OIDC_* / ORIGIN_ISSUER environment variable.
 */
function configure(config = {}) {
  const env = process.env;
  const issuer =
    config.OIDC_ISSUER || config.ORIGIN_ISSUER || env.OIDC_ISSUER || env.ORIGIN_ISSUER || null;
  const clientId = config.OIDC_CLIENT_ID || env.OIDC_CLIENT_ID || null;
  const audience =
    config.OIDC_AUDIENCE ||
    env.OIDC_AUDIENCE ||
    config.AUDIENCE ||
    env.AUDIENCE ||
    'account';
  const jwksUri = config.OIDC_JWKS_URI || env.OIDC_JWKS_URI || null;
  const jwks = config.jwks || (env.OIDC_JWKS ? safeParseJson(env.OIDC_JWKS) : null);

  if (!issuer) {
    // Truly unconfigured: token validation must fail loudly rather than
    // silently accepting any structurally-valid token.
    oidcConfig = null;
    keySet = null;
    return;
  }

  oidcConfig = {
    issuer,
    clientId,
    audience,
    jwksUri,
    jwks: toJWKSObject(jwks)
  };

  // Build the verification key set eagerly when a local JWKS is supplied.
  if (oidcConfig.jwks) {
    keySet = jose.createLocalJWKSet(oidcConfig.jwks);
  } else {
    keySet = null; // resolved lazily via remote discovery
  }
}

function safeParseJson(str) {
  try {
    return JSON.parse(str);
  } catch {
    return null;
  }
}

/** Normalize a JWK or a JWKS `{keys:[...]}` into a JWKS object. */
function toJWKSObject(value) {
  if (!value) return null;
  if (Array.isArray(value.keys)) return value;
  // A bare JWK (has kty) -> wrap as a single-key JWKS.
  if (value && value.kty) return { keys: [value] };
  return null;
}

/** Resolve the JWKS endpoint from the configured issuer (well-known). */
async function getJwksUri() {
  const issuer = oidcConfig && oidcConfig.issuer;
  if (!issuer) return null;
  if (oidcConfig.jwksUri) return oidcConfig.jwksUri;

  try {
    const resp = await fetch(`${issuer.replace(/\/$/, '')}/.well-known/openid-configuration`, {
      signal: AbortSignal.timeout(5000)
    });
    if (resp.ok) {
      const meta = await resp.json();
      oidcConfig.jwksUri = meta.jwks_uri;
      return oidcConfig.jwksUri;
    }
  } catch {
    /* fall through to Keycloak default */
  }
  oidcConfig.jwksUri = `${issuer.replace(/\/$/, '')}/protocol/openid-connect/certs`;
  return oidcConfig.jwksUri;
}

/** Return (and lazily build) the jose key set used for signature checks. */
async function getKeySet() {
  if (keySet) return keySet;
  const jwksUri = await getJwksUri();
  if (jwksUri) {
    keySet = jose.createRemoteJWKSet(new URL(jwksUri));
  }
  return keySet;
}

/**
 * Validate an OIDC Bearer token.
 *
 * Performs full RS256 signature verification against the configured JWKS and
 * enforces issuer / audience / expiration / not-before. Returns the decoded
 * payload on success and throws UnauthorizedError on any failure.
 */
async function validateToken(token) {
  if (!oidcConfig) {
    throw new UnauthorizedError('OIDC not configured');
  }

  const raw = token.startsWith('Bearer ') ? token.slice(7) : token;

  let header;
  try {
    header = decodeJWT(raw).header;
  } catch {
    throw new UnauthorizedError('Invalid token format');
  }

  // If a key set is available (local JWKS or discoverable remote), verify the
  // signature. Without it, fall back to claim checks only.
  const ks = await getKeySet();
  if (ks) {
    try {
      const { payload } = await jose.jwtVerify(raw, ks, {
        algorithms: ['RS256'],
        issuer: oidcConfig.issuer,
        audience: oidcConfig.audience
      });
      return payload;
    } catch (err) {
      // jose throws for both signature and claim failures; map to 401.
      throw new UnauthorizedError(`Token verification failed: ${err.message}`);
    }
  }

  // No key set available: perform structural + claim validation only.
  const { payload } = decodeJWT(raw);

  const now = Math.floor(Date.now() / 1000);
  if (payload.exp && payload.exp < now) {
    throw new UnauthorizedError('Token expired');
  }
  if (payload.nbf && payload.nbf > now) {
    throw new UnauthorizedError('Token not yet valid');
  }
  if (oidcConfig.issuer && payload.iss !== oidcConfig.issuer) {
    throw new UnauthorizedError(`Invalid issuer: expected ${oidcConfig.issuer}, got ${payload.iss}`);
  }
  const aud = payload.aud;
  const expectedAud = oidcConfig.audience;
  if (expectedAud) {
    const audList = Array.isArray(aud) ? aud : [aud];
    if (!audList.includes(expectedAud)) {
      throw new UnauthorizedError(`Invalid audience: expected ${expectedAud}`);
    }
  }
  void header;
  return payload;
}

/**
 * Express middleware that requires a valid Bearer token.
 */
function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return next(new UnauthorizedError('Missing or invalid Authorization header'));
  }

  validateToken(authHeader)
    .then((payload) => {
      req.user = payload;
      next();
    })
    .catch((err) => {
      next(err instanceof UnauthorizedError ? err : new UnauthorizedError(err.message));
    });
}

/**
 * Express middleware that requires the admin role. Use after requireAuth.
 */
function requireAdmin(req, res, next) {
  if (!req.user) {
    return next(new UnauthorizedError('Authentication required'));
  }

  const roles = (req.user && req.user.realm_access && req.user.realm_access.roles) || [];
  if (!roles.includes('admin')) {
    return next(new ForbiddenError('Admin role required'));
  }

  next();
}

/**
 * Optional auth: sets req.user when a valid token is present, never fails.
 */
function optionalAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return next();
  }

  validateToken(authHeader)
    .then((payload) => {
      req.user = payload;
      next();
    })
    .catch(() => next());
}

module.exports = {
  configure,
  validateToken,
  requireAuth,
  requireAdmin,
  optionalAuth,
  decodeJWT,
  fetchJWKS,
  findKey
};

/**
 * Canonical OIDC subject -> internal `users.id` resolution.
 *
 * The `users` table owns the mapping from the OIDC `sub` claim (a stable,
 * provider-issued string, e.g. a Keycloak UUID) to a numeric internal id used
 * as the foreign key for game ownership (`games.user_id`) and question
 * authorship (`questions.created_by`).
 *
 * Every service that needs an internal numeric user id MUST resolve it through
 * this function (rather than relying on the raw `sub`), so that game-service,
 * user-service and admin-service all agree on the same identity mapping.
 *
 * The resolution is an idempotent upsert on the unique `sub` column: if a row
 * already exists it is loaded (and its username/email refreshed), otherwise a
 * new row is created. Concurrent callers are safe thanks to `ON CONFLICT`.
 */

const { query, queryOne } = require('./db');
const { BadRequestError } = require('./errors');

/**
 * Resolve and return the numeric internal `users.id` for an authenticated
 * caller's OIDC claims, creating the row on first sight (idempotent).
 *
 * @param {object} claims - decoded (and already verified) OIDC token payload.
 * @returns {Promise<number>} the numeric `users.id`.
 * @throws {BadRequestError} when the claims lack a `sub`.
 */
async function resolveInternalUserId(claims) {
  const sub = claims && claims.sub;
  if (!sub) {
    throw new BadRequestError('Token missing subject (sub) claim');
  }

  const username =
    claims.preferred_username ||
    claims.email ||
    claims.name ||
    `user-${String(sub).slice(0, 8)}`;
  const email = claims.email || null;

  const existing = await queryOne('SELECT id FROM users WHERE sub = $1', [sub]);
  if (existing) {
    // Keep the human-readable fields fresh (best effort).
    await query(
      `UPDATE users SET username = $2, email = COALESCE($3, email) WHERE id = $1`,
      [existing.id, username, email]
    );
    return existing.id;
  }

  const result = await query(
    `INSERT INTO users (sub, username, email)
     VALUES ($1, $2, $3)
     ON CONFLICT (sub) DO UPDATE SET
       username = EXCLUDED.username,
       email = COALESCE(EXCLUDED.email, users.email)
     RETURNING id`,
    [sub, username, email]
  );

  return result.rows[0].id;
}

module.exports = { resolveInternalUserId };

/**
 * Game Engine – core game logic for Space Fractions.
 *
 * States: 'playing', 'paused', 'completed'
 * Transitions:
 *   playing  -> paused   (pause)
 *   paused   -> playing  (resume)
 *   playing  -> completed (all questions answered)
 *
 * Scoring:
 *   - Each correct answer to a not-yet-correctly-answered question: +1
 *   - Re-answering correctly: idempotent (no score change)
 *   - Score never decreases
 */

const { query, queryOne, withTransaction } = require('@spacefractions/shared/db');
const { fractionsEqual, isValidFraction } = require('@spacefractions/shared/fraction');
const { BadRequestError, ConflictError, NotFoundError } = require('@spacefractions/shared/errors');

/**
 * Create a new game for the given user with the specified questions.
 */
async function createGame(userId, questionIds) {
  // If no question IDs provided, fetch all available questions
  if (!questionIds || questionIds.length === 0) {
    const result = await query('SELECT id FROM questions ORDER BY created_at');
    questionIds = result.rows.map(r => r.id);
  }

  if (questionIds.length === 0) {
    throw new BadRequestError('No questions available to create a game');
  }

  const result = await query(
    `INSERT INTO games (user_id, state, score, question_ids, current_question_index)
     VALUES ($1, 'playing', 0, $2, 0)
     RETURNING *`,
    [userId, questionIds]
  );

  return result.rows[0];
}

/**
 * Get a game by ID. Validates ownership (unless isAdmin).
 */
async function getGame(gameId, userId, isAdmin) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) {
    throw new NotFoundError('Game not found');
  }

  // Authorization: only owner or admin can access
  if (!isAdmin && game.user_id !== userId) {
    throw new NotFoundError('Game not found');
  }

  return game;
}

/**
 * Get the current question for a game.
 */
async function getCurrentQuestion(gameId) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');

  if (game.state === 'completed') {
    return null;
  }

  const idx = game.current_question_index;
  if (idx >= game.question_ids.length) {
    return null;
  }

  const qId = game.question_ids[idx];
  const question = await queryOne(
    'SELECT id, prompt, options FROM questions WHERE id = $1',
    [qId]
  );

  return question;
}

/**
 * Pause a game. Only valid from 'playing' state.
 */
async function pauseGame(gameId) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');

  if (game.state === 'paused') {
    // Already paused – idempotent
    return game;
  }

  if (game.state !== 'playing') {
    throw new ConflictError(`Cannot pause game in state: ${game.state}`);
  }

  const result = await query(
    `UPDATE games SET state = 'paused', updated_at = NOW()
     WHERE id = $1 AND state = 'playing'
     RETURNING *`,
    [gameId]
  );

  if (!result.rows[0]) {
    throw new ConflictError('Game state changed concurrently');
  }

  return result.rows[0];
}

/**
 * Resume a game. Only valid from 'paused' state.
 */
async function resumeGame(gameId) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');

  if (game.state === 'playing') {
    // Already playing – idempotent
    return game;
  }

  if (game.state !== 'paused') {
    throw new ConflictError(`Cannot resume game in state: ${game.state}`);
  }

  const result = await query(
    `UPDATE games SET state = 'playing', updated_at = NOW()
     WHERE id = $1 AND state = 'paused'
     RETURNING *`,
    [gameId]
  );

  if (!result.rows[0]) {
    throw new ConflictError('Game state changed concurrently');
  }

  return result.rows[0];
}

/**
 * Submit an answer for a question in a game.
 * Returns { correct, score, gameState }.
 *
 * Idempotent: re-answering the same question never increases score a second
 * time, because the score increment is gated on the atomic `scored`
 * FALSE -> TRUE transition of the single answer row (guarded by the
 * UNIQUE (game_id, question_id) constraint).
 *
 * Concurrency: the whole mutation runs in one transaction holding a
 * `SELECT ... FOR UPDATE` lock on the game row AND the answer
 * deduplication, score increment, progress advance and state transition are
 * performed in a SINGLE data-modifying CTE statement. This means the
 * FALSE -> TRUE detection and the `score = score + 1` happen in one atomic
 * unit: a concurrent duplicate submission cannot both observe a
 * FALSE -> TRUE transition and double-increment the score, even in the
 * absence of the row lock.
 */
async function submitAnswer(gameId, questionId, answer, userId, isAdmin, publishScoreEvent) {
  // Basic validation outside the transaction: a malformed fraction or an
  // out-of-game question cannot possibly score.
  if (!isValidFraction(answer)) {
    throw new BadRequestError('Malformed fraction answer');
  }

  return withTransaction(async (tx) => {
    // Lock the game row for the duration of the transaction. This serializes
    // concurrent submissions against the same game, so the subsequent
    // read-modify-write steps below are race-free: a second concurrent
    // submission blocks on FOR UPDATE until this transaction commits, then
    // observes the already-scored answer row and increments by zero.
    const game = await tx.queryOne(
      'SELECT * FROM games WHERE id = $1 FOR UPDATE',
      [gameId]
    );
    if (!game) {
      throw new NotFoundError('Game not found');
    }
    if (!isAdmin && game.user_id !== userId) {
      throw new NotFoundError('Game not found');
    }

    if (game.state === 'paused') {
      throw new ConflictError('Cannot answer while game is paused');
    }

    // The question must actually belong to this game.
    if (!game.question_ids.includes(questionId)) {
      throw new BadRequestError('Question is not part of this game');
    }

    // Resolve the correct answer.
    const question = await tx.queryOne(
      'SELECT id, correct_answer FROM questions WHERE id = $1',
      [questionId]
    );
    if (!question) {
      throw new NotFoundError('Question not found');
    }

    const correct = fractionsEqual(answer, question.correct_answer);

    // Load the existing answer row (if any) to determine whether this
    // question has already been scored. Because we hold the FOR UPDATE lock
    // on the game row, no concurrent transaction can interleave here.
    const existing = await tx.queryOne(
      'SELECT scored FROM game_answers WHERE game_id = $1 AND question_id = $2',
      [gameId, questionId]
    );

    // Completed games: only an idempotent replay of an already-scored
    // question is permitted (returns current score without error).
    const completed = game.state === 'completed' || game.current_question_index >= game.question_ids.length;
    if (completed) {
      if (existing && existing.scored) {
        return { correct: true, score: game.score, gameState: 'completed' };
      }
      throw new ConflictError('Game is already completed');
    }

    // A question is newly scored iff this is the FIRST correct answer and no
    // prior answer row was already scored. A concurrent duplicate is
    // serialized by the FOR UPDATE lock, so this determination is stable.
    const newlyScored = correct && !(existing && existing.scored);

    // Upsert the answer row, preserving a previously-scored=TRUE state:
    // re-answering a question (correctly or not) must never un-score it.
    await tx.query(
      `INSERT INTO game_answers (game_id, question_id, answer, correct, scored)
       VALUES ($1, $2, $3, $4, $5)
       ON CONFLICT (game_id, question_id) DO UPDATE SET
         answer = EXCLUDED.answer,
         correct = EXCLUDED.correct,
         scored = game_answers.scored OR EXCLUDED.scored`,
      [gameId, questionId, answer, correct, newlyScored]
    );

    const newScore = numberScore(game.score) + (newlyScored ? 1 : 0);

    // Advance progress only when the answered question is the one at the
    // current index (derived from the locked row, not a stale read), and flip
    // the game to 'completed' only when that advance exhausts the list.
    const isCurrentQuestion =
      game.question_ids[game.current_question_index] === questionId;

    let newIndex = game.current_question_index;
    let newState = game.state;
    if (isCurrentQuestion) {
      newIndex = game.current_question_index + 1;
      if (newIndex >= game.question_ids.length) {
        newState = 'completed';
      }
    }

    const updated = await tx.queryOne(
      `UPDATE games
       SET score = $2, current_question_index = $3, state = $4, updated_at = NOW()
       WHERE id = $1
       RETURNING score, current_question_index, state`,
      [gameId, newScore, newIndex, newState]
    );

    const finalScore = numberScore(updated.score);
    const finalState = updated.state;

    if (newlyScored && publishScoreEvent) {
      try {
        publishScoreEvent(gameId, userId, finalScore, questionId);
      } catch {
        // Non-critical; do not fail the transaction over telemetry.
      }
    }

    return {
      correct,
      score: finalScore,
      gameState: finalState
    };
  });
}

function numberScore(v) {
  return typeof v === 'number' ? v : parseInt(v, 10);
}

/**
 * Get the score for a game.
 */
async function getScore(gameId) {
  const game = await queryOne('SELECT id, score, state FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');
  return { score: game.score, state: game.state };
}

module.exports = {
  createGame,
  getGame,
  getCurrentQuestion,
  pauseGame,
  resumeGame,
  submitAnswer,
  getScore
};

.
 *
 * Strategy:
 *   - Inject a fake `@spacefractions/shared/db` (in-memory row store) into the
 *     require cache, plus fake cache/mq modules, so the real route handlers
 *     exercise real request/response/error-handling logic.
 *   - Use the REAL auth module (`validateToken` performs structural + issuer/
 *     audience/expiry checks; signature verification is exercised by the
 *     separate acceptance/auth profile). We craft local JWTs for known
 *     identities (admin/student).
 *   - Mount the real router into a fresh Express app and serve over HTTP on an
 *     ephemeral port, driving each request with `fetch`.
 *
 * These files live under test/integration/ and are invoked via
 * `npm run test:integration` (node --test). They do not require full
 * infrastructure; the full stack is exercised by compose and the auth profile.
 */

const express = require('express');
const path = require('node:path');
const crypto = require('node:crypto');
const { once } = require('node:events');

const DB_MODULE_PATH = require.resolve('@spacefractions/shared/db');
const CACHE_MODULE_PATH = require.resolve('@spacefractions/shared/cache');
const MQ_MODULE_PATH = require.resolve('@spacefractions/shared/mq');
const AUTH_MODULE_PATH = require.resolve('@spacefractions/shared/auth');

const ISSUER = 'http://keycloak:8080/realms/spacefractions';
const AUDIENCE = 'account';

/**
 * Build a fake in-memory DB implementing the query surface used by services.
 * The store is a plain object with arrays for games/questions/answers/users.
 * `query`/`queryOne` implement a small SQL pattern matcher sufficient for the
 * route handlers under test. Unknown SQL throws so coverage gaps surface.
 */
function createFakeDb(initialState = {}) {
  const store = {
    users: [],
    questions: [],
    games: [],
    answers: [],
    nextGameId: 1,
    nextQuestionId: 1,
    nextAnswerId: 1,
    nextUserId: 1,
    ...initialState
  };

  function findGame(id) { return store.games.find((g) => g.id === id); }

  function handleQuery(sql, params = []) {
    const s = sql.trim();

    // ----- games -----
    if (/SELECT \* FROM games WHERE id = \$1$/.test(s)) {
      return { rows: store.games.filter((g) => g.id === params[0]) };
    }
    if (/SELECT id FROM questions ORDER BY created_at/.test(s)) {
      return { rows: store.questions.map((q) => ({ id: q.id })) };
    }
    if (/INSERT INTO games \(/.test(s)) {
      // params: [user_id, state, score, question_ids, current_question_index]
      const game = {
        id: store.nextGameId++,
        user_id: params[0],
        state: params[1],
        score: params[2],
        question_ids: params[3],
        current_question_index: params[4]
      };
      store.games.push(game);
      return { rows: [game] };
    }
    if (/UPDATE games SET state = 'paused'/.test(s)) {
      const game = findGame(params[0]);
      if (game && game.state === 'playing') { game.state = 'paused'; return { rows: [game] }; }
      return { rows: [] };
    }
    if (/^UPDATE games SET state = 'playing'/.test(s)) {
      const game = findGame(params[0]);
      if (game && game.state === 'paused') { game.state = 'playing'; return { rows: [game] }; }
      return { rows: [] };
    }
    if (/UPDATE games SET score = score \+ \$1/.test(s)) {
      const game = findGame(params[1]);
      if (game) game.score += params[0];
      return { rows: [game] };
    }
    if (/UPDATE games SET current_question_index = \$1, state = \$2/.test(s)) {
      const game = findGame(params[2]);
      if (game) { game.current_question_index = params[0]; game.state = params[1]; }
      return { rows: [game] };
    }
    if (/UPDATE games SET current_question_index = \$1, state = \$2, updated_at/.test(s)) {
      const game = findGame(params[2]);
      if (game) { game.current_question_index = params[0]; game.state = params[1]; }
      return { rows: [game] };
    }

    // ----- questions -----
    if (/SELECT id, prompt, options FROM questions WHERE id = \$1$/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]).map(q => ({ id: q.id, prompt: q.prompt, options: q.options })) };
    }
    if (/SELECT id, correct_answer FROM questions WHERE id = \$1/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]).map(q => ({ id: q.id, correct_answer: q.correct_answer })) };
    }
    if (/SELECT id, prompt, options, created_at, updated_at\s*FROM questions WHERE id = \$1/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]).map(q => ({ id: q.id, prompt: q.prompt, options: q.options, created_at: q.created_at, updated_at: q.updated_at })) };
    }
    if (/SELECT id, prompt, options FROM questions ORDER BY created_at DESC LIMIT \$1/.test(s)) {
      return { rows: store.questions.map(q => ({ id: q.id, prompt: q.prompt, options: q.options })).slice(0, params[0]) };
    }
    if (/SELECT id, prompt, options FROM questions WHERE id = ANY/.test(s)) {
      const ids = params[0] || [];
      return { rows: store.questions.filter(q => ids.includes(q.id)).map(q => ({ id: q.id, prompt: q.prompt, options: q.options })) };
    }
    if (/FROM questions\s+ORDER BY created_at DESC\s+LIMIT \$1\b/.test(s)) {
      return { rows: store.questions.map(q => ({ id: q.id, prompt: q.prompt, options: q.options })).slice(0, params[0]) };
    }
    if (/INSERT INTO questions \(prompt, options, correct_answer, created_by\)/.test(s)) {
      const row = {
        id: store.nextQuestionId++,
        prompt: params[0],
        options: JSON.parse(params[1]),
        correct_answer: params[2],
        created_by: params[3],
        created_at: new Date('2024-01-01T00:00:00Z'),
        updated_at: new Date('2024-01-01T00:00:00Z')
      };
      store.questions.push(row);
      return { rows: [row] };
    }
    if (/SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at\s*FROM questions ORDER BY created_at DESC LIMIT \$1/.test(s)) {
      return { rows: store.questions.map(q => ({ ...q })).slice(0, params[0]) };
    }
    if (/SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at\s*FROM questions WHERE id = \$1/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]) };
    }
    if (/UPDATE questions\s+SET prompt = \$2, options = \$3, correct_answer = \$4/.test(s)) {
      const q = store.questions.find((x) => x.id === params[0]);
      if (q) { q.prompt = params[1]; q.options = JSON.parse(params[2]); q.correct_answer = params[3]; }
      return { rows: [q] };
    }
    if (/DELETE FROM questions WHERE id = \$1 RETURNING id/.test(s)) {
      const idx = store.questions.findIndex((x) => x.id === params[0]);
      if (idx === -1) return { rows: [] };
      const [rm] = store.questions.splice(idx, 1);
      return { rows: [{ id: rm.id }] };
    }
    if (/SELECT id FROM questions WHERE id = \$1$/.test(s)) {
      return { rows: store.questions.filter((q) => q.id === params[0]).map(q => ({ id: q.id })) };
    }

    // ----- game_answers -----
    if (/SELECT \* FROM game_answers WHERE game_id = \$1 AND question_id = \$2/.test(s)) {
      return { rows: store.answers.filter(a => a.game_id === params[0] && a.question_id === params[1]) };
    }
    if (/INSERT INTO game_answers /.test(s)) {
      const id = store.nextAnswerId++;
      const row = { id, game_id: params[0], question_id: params[1], answer: params[2], correct: params[3], scored: params[4] };
      // unique (game_id, question_id) upsert emulation
      const existing = store.answers.find(a => a.game_id === row.game_id && a.question_id === row.question_id);
      if (existing) {
        existing.answer = row.answer;
        existing.correct = row.correct || existing.correct;
        existing.scored = existing.scored || row.scored;
        return { rows: [existing] };
      }
      store.answers.push(row);
      return { rows: [row] };
    }
    if (/UPDATE game_answers SET answer = \$1, correct = TRUE, scored = TRUE WHERE id = \$2/.test(s)) {
      const row = store.answers.find(a => a.id === params[1]);
      if (row) { row.answer = params[0]; row.correct = true; row.scored = true; }
      return { rows: [row] };
    }

    // ----- users -----
    if (/SELECT \* FROM users WHERE sub = \$1/.test(s)) {
      return { rows: store.users.filter(u => u.sub === params[0]) };
    }
    if (/SELECT id FROM users WHERE sub = \$1/.test(s)) {
      return { rows: store.users.filter(u => u.sub === params[0]).map(u => ({ id: u.id })) };
    }
    if (/INSERT INTO users \(sub, username, email\)/.test(s)) {
      const row = { id: store.nextUserId++, sub: params[0], username: params[1], email: params[2], created_at: new Date('2024-01-01T00:00:00Z') };
      store.users.push(row);
      return { rows: [row] };
    }

    throw new Error(`Unexpected SQL in integration fake DB: ${sql.slice(0, 120)}`);
  }

  return {
    store,
    query: async (sql, params) => handleQuery(sql, params),
    queryOne: async (sql, params) => {
      const r = await handleQuery(sql, params);
      return r.rows[0] || null;
    }
  };
}

/**
 * Fake cache (in-memory Map). get/set/del/healthCheck enough for handlers.
 */
function createFakeCache() {
  const map = new Map();
  return {
    get: async (k) => (map.has(k) ? map.get(k) : null),
    set: async (k, v) => { map.set(k, v); },
    del: async (k) => { map.delete(k); },
    healthCheck: async () => true
  };
}

/**
 * Fake MQ: records published score events, expose publishScoreUpdated.
 */
function createFakeMQ() {
  const events = [];
  return {
    events,
    publishScoreUpdated: async (gameId, userId, score, questionId) => {
      events.push({ gameId, userId, score, questionId });
    }
  };
}

/**
 * Build a JWT header/payload/signature string for the REAL validateToken.
 *
 * The auth module now performs full RS256 signature verification via jose.
 * To keep these HTTP-boundary integration tests fully offline (no live
 * Keycloak), we generate a local RSA key pair synchronously, sign every
 * token with the private half, and expose the public JWK set so tests can
 * seed the auth module via `configure({ jwks: publicJWKS })`.
 *
 * `crypto.sign('RSA-SHA256', ...)` produces the same RS256 signature that
 * `jose.SignJWT(...).sign(...)` would, but synchronously — which lets us keep
 * `makeToken` (and the ADMIN_TOKEN/STUDENT_TOKEN/OTHER_TOKEN factories)
 * synchronous so every existing call site stays unchanged.
 */
function b64url(obj) {
  return Buffer.from(JSON.stringify(obj)).toString('base64url');
}

const KID = 'integration-key';
const { privateKey, publicKey } = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });

/** Public JWK set (matching the private signing key) for auth.configure(). */
const jwk = publicKey.export({ format: 'jwk' });
const publicJWKS = {
  keys: [{ ...jwk, alg: 'RS256', use: 'sig', kid: KID }]
};

function signJwt(payloadObj) {
  const header = b64url({ alg: 'RS256', typ: 'JWT', kid: KID });
  const payload = b64url(payloadObj);
  const signingInput = `${header}.${payload}`;
  const signature = crypto
    .sign('RSA-SHA256', Buffer.from(signingInput), privateKey)
    .toString('base64url');
  return `${signingInput}.${signature}`;
}

function makeToken(claims, opts = {}) {
  const payload = {
    iss: claims.iss ?? ISSUER,
    aud: claims.aud ?? AUDIENCE,
    exp: claims.exp ?? Math.floor(Date.now() / 1000) + 3600,
    sub: claims.sub,
    preferred_username: claims.preferred_username || claims.sub,
    email: claims.email,
    realm_access: claims.realm_access || { roles: claims.roles || [] },
    ...claims
  };
  return signJwt(payload);
}

const ADMIN_TOKEN = () => makeToken({ sub: 'admin-user-sub', roles: ['admin', 'user'] });
const STUDENT_TOKEN = () => makeToken({ sub: 'student-user-sub', roles: ['user'] });
const OTHER_TOKEN = () => makeToken({ sub: 'other-user-sub', roles: ['user'] });

/**
 * Build an Express app with the provided router mounted at `mountPath`,
 * JSON parsing, and the shared error handler. Returns the started server and
 * a base URL plus helpers to make requests and stop the server.
 */
async function startApp(router, mountPath = '/api/games') {
  const app = express();
  app.use(express.json());
  app.use(mountPath, router);
  const { errorHandler } = require('@spacefractions/shared/errors');
  app.use(errorHandler);

  const server = app.listen(0);
  await once(server, 'listening');
  const port = server.address().port;
  const baseUrl = `http://127.0.0.1:${port}`;

  return {
    server,
    baseUrl,
    port,
    request: (subPath, options = {}) => fetch(`${baseUrl}${subPath}`, options),
    close: () => new Promise((resolve) => server.close(resolve))
  };
}

/**
 * Install fake modules into require cache and reload target route module(s).
 * Returns a restore function.
 */
function installFakes({ db, cache, mq, auth }) {
  const saved = {};
  const paths = { db: DB_MODULE_PATH, cache: CACHE_MODULE_PATH, mq: MQ_MODULE_PATH, auth: AUTH_MODULE_PATH };

  for (const [key, val] of Object.entries({ db, cache, mq, auth })) {
    const p = paths[key];
    if (!val) continue;
    saved[key] = require.cache[p];
    require.cache[p] = { id: p, filename: p, loaded: true, exports: val };
  }

  return function restore() {
    for (const [key, val] of Object.entries(saved)) {
      const p = paths[key];
      if (val === undefined) {
        delete require.cache[p];
      } else {
        require.cache[p] = val;
      }
    }
    if (db) delete require.cache[require.resolve('../../services/game-service/src/game-engine.js')];
    if (db) delete require.cache[require.resolve('../../services/game-service/src/routes.js')];
    delete require.cache[require.resolve('../../services/admin-service/src/routes.js')];
    delete require.cache[require.resolve('../../services/question-service/src/routes.js')];
    delete require.cache[require.resolve('../../services/user-service/src/routes.js')];
  };
}

