      ['/questions', 'POST'],
      ['/questions/1', 'GET'],
      ['/questions/1', 'PUT'],
      ['/questions/1', 'DELETE']
    ];
    for (const [p, method] of cases) {
      const opts = { method };
      if (method === 'POST' || method === 'PUT') {
        opts.headers = { 'Content-Type': 'application/json' };
        opts.body = JSON.stringify(VALID_PAYLOAD);
