    // submission blocks on FOR UPDATE until this transaction commits, then
    // observes the already-scored answer row and increments by zero.
    const game = await tx.queryOne(
      'SELECT * FROM games WHERE id = $1 FOR UPDATE',
      [gameId]
    );
    if (!game) {
      throw new NotFoundError('Game not found');
    }
    if (!isAdmin && game.user_id !== userId) {
      throw new NotFoundError('Game not found');
    }

    if (game.state === 'paused') {
      throw new ConflictError('Cannot answer while game is paused');
    }

    // The question must actually belong to this game.
    if (!game.question_ids.includes(questionId)) {
      throw new BadRequestError('Question is not part of this game');
    }

    // Resolve the correct answer.
    const question = await tx.queryOne(
      'SELECT id, correct_answer FROM questions WHERE id = $1',
      [questionId]
    );
    if (!question) {
      throw new NotFoundError('Question not found');
    }

    const correct = fractionsEqual(answer, question.correct_answer);

    // Load the existing answer row (if any) to determine whether this
    // question has already been scored. Because we hold the FOR UPDATE lock
    // on the game row, no concurrent transaction can interleave here.
    const existing = await tx.queryOne(
      'SELECT scored FROM game_answers WHERE game_id = $1 AND question_id = $2',
      [gameId, questionId]
    );

    // Completed games: answering after completion is rejected. Idempotent
    // re-answer of an already-scored question is only permitted while the
    // game is still in progress (handled below via `newlyScored`).
    const completed = game.state === 'completed' || game.current_question_index >= game.question_ids.length;
    if (completed) {
      throw new ConflictError('Game is already completed');
    }

    // A question is newly scored iff this is the FIRST correct answer and no
    // prior answer row was already scored. A concurrent duplicate is
    // serialized by the FOR UPDATE lock, so this determination is stable.
    const newlyScored = correct && !(existing && existing.scored);

    // Upsert the answer row, preserving a previously-scored=TRUE state:
    // re-answering a question (correctly or not) must never un-score it.
    await tx.query(
      `INSERT INTO game_answers (game_id, question_id, answer, correct, scored)
       VALUES ($1, $2, $3, $4, $5)
       ON CONFLICT (game_id, question_id) DO UPDATE SET
         answer = EXCLUDED.answer,
         correct = EXCLUDED.correct,
         scored = game_answers.scored OR EXCLUDED.scored`,
      [gameId, questionId, answer, correct, newlyScored]
    );

    const newScore = numberScore(game.score) + (newlyScored ? 1 : 0);

    // Advance progress only when the answered question is the one at the
    // current index (derived from the locked row, not a stale read), and flip
    // the game to 'completed' only when that advance exhausts the list.
    const isCurrentQuestion =
      game.question_ids[game.current_question_index] === questionId;

    let newIndex = game.current_question_index;
    let newState = game.state;
    if (isCurrentQuestion) {
      newIndex = game.current_question_index + 1;
      if (newIndex >= game.question_ids.length) {
        newState = 'completed';
      }
    }

    const updated = await tx.queryOne(
      `UPDATE games
       SET score = $2, current_question_index = $3, state = $4, updated_at = NOW()
       WHERE id = $1
       RETURNING score, current_question_index, state`,
      [gameId, newScore, newIndex, newState]
    );

    const finalScore = numberScore(updated.score);
    const finalState = updated.state;

    if (newlyScored && publishScoreEvent) {
      try {
        publishScoreEvent(gameId, userId, finalScore, questionId);
      } catch {
        // Non-critical; do not fail the transaction over telemetry.
      }
    }

    return {
      correct,
      score: finalScore,
      gameState: finalState
    };
  });
}

function numberScore(v) {
  return typeof v === 'number' ? v : parseInt(v, 10);
}

/**
 * Get the score for a game.
 */
async function getScore(gameId) {
  const game = await queryOne('SELECT id, score, state FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');
  return { score: game.score, state: game.state };
}

module.exports = {
  createGame,
  getGame,
  getCurrentQuestion,
  pauseGame,
  resumeGame,
  submitAnswer,
  getScore
};
